import * as db from './db.js';
import {CHANNELS,RATIOS,uid,escapeHTML as esc,safeURL,formatBytes,formatTime,engagement,researchSummary,icsEvent,validateReference,validateTrim} from './domain.js';
import {inspect,exportMedia,paint} from './media.js';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',media:'M4 4h16v16H4z M4 15l5-5 6 6 3-3 2 2 M15 8h.01',studio:'M4 4h16v16H4z M10 8l6 4-6 4z',calendar:'M4 5h16v16H4z M4 10h16 M8 3v4 M16 3v4',research:'M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16 M16 16l6 6 M6 11l3-3 3 2 3-4',workflow:'M4 3h6v6H4z M14 15h6v6h-6z M7 9v9h7 M17 15V6h-7',channels:'M9 8l3-3a5 5 0 0 1 7 7l-3 3 M15 16l-3 3a5 5 0 0 1-7-7l3-3 M9 15l6-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',close:'M6 6l12 12 M6 18 18 6',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',check:'M5 12l4 4L19 6',chevron:'M8 5l7 7-7 7',play:'M8 4l12 8-12 8z',pause:'M8 5v14 M16 5v14',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 13h8 M8 17h6',music:'M9 18V5l11-2v13 M9 8l11-2 M9 18c0 4-6 4-6 1 0-2 6-3 6-1 M20 16c0 4-6 4-6 1 0-2 6-3 6-1',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l3 2',external:'M14 3h7v7 M21 3 10 14 M10 3H3v18h18v-7',menu:'M4 6h16 M4 12h16 M4 18h16',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7h.01',approve:'M12 3l8 3v6c0 4-8 9-8 9s-8-5-8-9V6z M8 12l3 3 5-6',leaf:'M20 3C7 2 2 9 5 16c7 4 15-1 15-13 M4 21l11-12',undo:'M9 4 3 10l6 6 M3 10h10a7 7 0 0 1 7 10'};
const icon=(name,extra='')=>`<svg class="icon ${extra}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
let state={media:[],drafts:[],references:[],plans:[],settings:{id:'brand',name:'Corebridge',color:'#d85830'},workflows:[]};
let filter='all',search='',cleanup=()=>{},renderSerial=0,toastTimer,uploading=false,exporting=false;
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
const dateLabel=value=>new Date(value).toLocaleDateString(undefined,{day:'numeric',month:'short'});
const route=()=>location.hash.slice(1).split('/')[0]||'media';
const routeID=()=>location.hash.slice(1).split('/')[1];
const navItems=[['media','media','Media library'],['studio','studio','Studio'],['calendar','calendar','Calendar'],['research','research','Research'],['workflows','workflow','Workflows'],['approvals','approve','Approvals'],['channels','channels','Connections']];
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function button(label,action,style='primary',symbol='plus'){return `<button class="button ${style}" data-action="${action}">${symbol?icon(symbol):''}${label}</button>`;}
function empty(symbol,title,description,action='upload',label='Upload your first file'){return `<div class="empty" id="dropzone"><div class="empty-symbol">${icon(symbol)}</div><h2>${title}</h2><p>${description}</p>${action?button(label,action):''}</div>`;}
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function closeDialog(){dialog.close();dialog.innerHTML='';}
function modal(title,description,body,onSubmit){dialog.innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><p>${description}</p><form>${body}<p class="form-error" role="alert"></p></form>`;dialog.querySelector('form').addEventListener('submit',async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{await onSubmit(new FormData(e.target),e.target);closeDialog();await refresh();}catch(error){dialog.querySelector('.form-error').textContent=error.message;submit.disabled=false;}});dialog.showModal();}
async function refresh(){const values=await Promise.all(['media','drafts','references','plans','workflows'].map(db.all));['media','drafts','references','plans','workflows'].forEach((key,i)=>state[key]=values[i]);state.settings=await db.get('settings','brand')||state.settings;await render();}
function shell(content){const r=route();app.innerHTML=`<div class="shell"><aside class="sidebar"><button class="icon-button mobile-close" data-action="menu" aria-label="Close navigation">${icon('close')}</button><a href="#welcome" class="brand"><img src="icon.svg" alt="">drop<sup>EARLY ACCESS</sup></a><div class="workspace-switch"><div class="avatar">${esc((state.settings.name||'CW').slice(0,2).toUpperCase())}</div><div><strong>${esc(state.settings.name||'My workspace')}</strong><small>Personal workspace</small></div></div><div class="nav-group">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${navItems.map(([id,symbol,label])=>`<a href="#${id}" ${r===id?'aria-current="page"':''} class="${r===id?'active':''}">${icon(symbol)}${label}${id==='approvals'&&state.drafts.filter(d=>d.status==='review').length?`<span class="count">${state.drafts.filter(d=>d.status==='review').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><span>Good content goes further.</span>One place to research, prepare and plan your next post.</div><nav class="nav"><a href="#settings" class="${r==='settings'?'active':''}">${icon('settings')}Workspace settings</a></nav><div class="credit">A product by Corebridge</div></div></aside><div class="main-wrap"><header class="topbar"><div class="inline"><button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span>/</span> <b>${esc(navItems.find(n=>n[0]===r)?.[2]||({welcome:'Meet Drop',settings:'Settings'}[r])||'Media library')}</b></div></div><div class="top-actions"><span class="device-tag"><span class="dot"></span> Saved on this device</span><a href="#welcome">About Drop</a><a class="avatar" href="#settings" aria-label="Workspace settings">${esc((state.settings.name||'CW').slice(0,2).toUpperCase())}</a></div></header><main id="main" tabindex="-1">${content}<footer class="footer"><span>Drop · Content, carried further.</span><span>Personal preview · v0.1</span></footer></main></div></div><input id="upload-input" type="file" accept="video/*,image/*,audio/*" multiple hidden>`;document.querySelector('#upload-input').addEventListener('change',e=>upload(e.target.files));bindDrop();}
async function render(){const serial=++renderSerial;cleanup();cleanup=()=>{};const r=route();let content;if(r==='welcome')content=welcomePage();else if(r==='studio')content=studioPage();else if(r==='research')content=researchPage();else if(r==='calendar')content=calendarPage();else if(r==='channels')content=channelsPage();else if(r==='settings')content=settingsPage();else if(r==='approvals')content=approvalsPage();else if(r==='workflows')content=workflowsPage();else content=mediaPage();shell(content);if(r==='studio'&&routeID())await mountStudio(serial);}
function welcomePage(){return `<section class="home-hero"><div><span class="intro-note"><span class="dot"></span> Introducing Drop, by Corebridge</span><h1>Content,<br>carried further.</h1><p>Find your next idea. Give your content a new shape. Make a plan to get it out into the world.</p><div class="inline"><a class="button primary" href="#media">Open your workspace ${icon('arrow')}</a><a class="button secondary" href="#research">Explore research</a></div><p class="help" style="margin-top:17px">A working personal preview. Your files stay in this browser.</p></div><div class="hero-board"><div class="panel"><div class="panel-title"><h3 style="margin:0">A little more from every idea.</h3><span class="pill">Your workflow</span></div>${[['research','Find a useful reference','Save what inspires your next post.'],['studio','Make it your own','Crop, caption and brand your content.'],['calendar','Give it a place in the week','Plan a post and export a reminder.']].map(([i,t,d])=>`<div class="list-row"><div class="inline"><div class="avatar">${icon(i)}</div><div><h3>${t}</h3><p>${d}</p></div></div>${icon('chevron')}</div>`).join('')}</div></div></section><section class="home-steps"><article><span class="eyebrow">01 / UNDERSTAND</span><h2>Start with a better question.</h2><p>Save source posts, record public metrics and compare references. Turn an observation into something worth testing.</p></article><article><span class="eyebrow">02 / PREPARE</span><h2>One file. A few new forms.</h2><p>Prepare portrait, square or landscape versions. Add your brand and timed captions, then export a real file.</p></article><article><span class="eyebrow">03 / PLAN</span><h2>Keep the next step clear.</h2><p>Save drafts, review them and plan publication. Direct social publishing is a future integration, clearly marked in Connections.</p></article></section>`;}
function mediaPage(){const list=state.media.filter(m=>(filter==='all'||m.kind===filter)&&m.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.created-a.created);return `${heading('Media library','A home for your content. A starting point for what comes next.',button('Upload content','upload','primary','upload'))}<section class="banner"><div><span class="eyebrow">MAKE SOMETHING OF IT</span><h2>Your next post is already in your files.</h2><p>Drop in a video or image. Find a new angle, add your words and prepare it for your next channel.</p><button class="link-button" data-action="upload">Choose a file ${icon('arrow')}</button></div><div class="banner-art" aria-hidden="true"><div class="paper">${icon('media')}<i></i><i></i></div><div class="paper">${icon('studio')}<i></i><i></i></div></div></section><div class="stats"><div class="stat"><div><small>In your library</small><strong>${state.media.length} <span style="font-size:11px;letter-spacing:0">files</span></strong></div>${icon('media')}</div><div class="stat"><div><small>Saved preparations</small><strong>${state.drafts.length}</strong></div>${icon('studio')}</div><div class="stat"><div><small>In your plan</small><strong>${state.plans.filter(p=>p.status!=='done').length}</strong></div>${icon('calendar')}</div></div><div class="toolbar"><div class="tabs" role="group" aria-label="Filter media">${[['all','All content'],['video','Videos'],['image','Images'],['audio','Audio']].map(([id,label])=>`<button class="tab ${filter===id?'active':''}" data-filter="${id}" aria-pressed="${filter===id}">${label}</button>`).join('')}</div><div class="search-wrap">${icon('research')}<input id="media-search" aria-label="Search media" placeholder="Find something in your library" value="${esc(search)}"></div></div><div id="upload-status" role="status"></div><div class="media-grid">${list.length?list.map(m=>`<article class="media-card"><div class="thumb">${m.thumbnail?`<img src="${esc(m.thumbnail)}" alt="" loading="lazy">`:icon(m.kind==='audio'?'music':'media')}<span class="duration">${m.kind==='image'?`${m.width} × ${m.height}`:formatTime(m.duration)}</span></div><div class="card-body"><h3 title="${esc(m.name)}">${esc(m.name)}</h3><div class="card-meta"><span>${esc(m.kind.toUpperCase())} · ${formatBytes(m.size)}</span><span>${dateLabel(m.created)}</span></div><div class="card-actions">${m.kind!=='audio'?`<a class="button secondary small" href="#studio/${m.id}">${icon('studio')}Prepare</a>`:`<button class="button secondary small" data-action="download-original" data-id="${m.id}">${icon('download')}Download</button>`}<div class="inline"><button class="icon-button" data-action="download-original" data-id="${m.id}" aria-label="Download original ${esc(m.name)}">${icon('download')}</button><button class="icon-button" data-action="rename" data-id="${m.id}" aria-label="Rename ${esc(m.name)}">${icon('file')}</button><button class="icon-button" data-action="delete-media" data-id="${m.id}" aria-label="Delete ${esc(m.name)}">${icon('trash')}</button></div></div></div></article>`).join(''):empty('upload',search?'No matching files':'Your library starts here',search?'Try a different search or content type.':'Drag a video, image or audio file here, or choose one from your device.')} </div><p class="footnote">Files are stored in this browser, not uploaded to a server. Up to 250 MB per file. Keep originals backed up; clearing site data removes this workspace.</p>`;}
function studioPage(){const id=routeID(),media=state.media.find(m=>m.id===id);if(!media||media.kind==='audio')return `${heading('Studio','A small set of tools to give your content a new shape.')}<div class="panel">${state.drafts.length?`<div class="panel-title"><h2>Saved drafts</h2><span class="pill">${state.drafts.length}</span></div>${state.drafts.map(d=>`<div class="list-row"><div><h3>${esc(d.title)}</h3><p>${d.ratio} · ${d.status==='review'?'Awaiting review':d.status==='approved'?'Approved':'Draft'} · ${dateLabel(d.updated)}</p></div><a class="button secondary small" href="#studio/${d.mediaId}">Open ${icon('arrow')}</a></div>`).join('')}`:empty('studio','Make your first preparation','Choose a video or image from your library to crop, caption and brand it.','go-media','Choose from library')}</div>`;const draft=state.drafts.find(d=>d.mediaId===id)||{id:uid(),mediaId:id,title:media.name.replace(/\.[^.]+$/,''),ratio:'9:16',start:0,end:Math.min(media.duration||10,60),position:.5,brand:state.settings.name,color:state.settings.color,captions:[],status:'draft'};window.activeDraft=structuredClone(draft);return `${heading('Prepare your content','A new format. Your voice. Ready for the next step.',`<div class="inline"><a class="button secondary" href="#media">Back to library</a>${button('Save draft','save-draft','primary','check')}</div>`)}<div class="studio-layout"><section><div class="panel"><div class="panel-title"><span class="small muted">${esc(media.name)}</span><span class="pill">${media.kind==='video'?formatTime(media.duration):'Image'}</span></div><div class="preview-stage"><canvas id="preview-canvas" aria-label="Prepared content preview"></canvas></div>${media.kind==='video'?`<div class="preview-controls"><button id="play-preview" class="icon-button" aria-label="Play or pause preview">${icon('play')}</button><input type="range" id="scrubber" aria-label="Preview position" min="0" max="${media.duration}" step=".05" value="${draft.start}"><span id="preview-time" class="small muted">${formatTime(draft.start)}</span></div>`:''}<div class="field" style="margin-top:20px"><label for="draft-title">Preparation name</label><input id="draft-title" value="${esc(draft.title)}" maxlength="160"></div><div class="notice" style="margin-bottom:0">${media.kind==='video'?'Video export runs in real time in this tab. Keep the page open while it records. The export format depends on your browser, usually WebM.':'Your prepared image exports as a PNG, with the selected crop, brand and caption.'}</div></div><div id="draft-status" class="help" role="status">${state.drafts.some(d=>d.mediaId===id)?'Loaded your saved draft. Changes need to be saved.':'New preparation. Save a draft to keep your settings.'}</div></section><aside class="panel"><h2>Make it fit.</h2><label>Format</label><div class="ratio-group">${Object.keys(RATIOS).map(r=>`<button class="ratio-option ${draft.ratio===r?'active':''}" data-ratio="${r}" aria-pressed="${draft.ratio===r}"><span class="ratio-shape ${r==='1:1'?'square':r==='16:9'?'wide':''}"></span>${r}<span class="small">${r==='9:16'?'Portrait':r==='1:1'?'Square':'Landscape'}</span></button>`).join('')}</div><div class="field" style="margin-top:18px"><label for="crop-position">Horizontal crop position</label><input id="crop-position" type="range" min="0" max="1" step=".01" value="${draft.position}"><p class="help">Move the crop to keep your subject in view.</p></div>${media.kind==='video'?`<div class="form-grid"><div class="field"><label for="trim-start">Start (seconds)</label><input id="trim-start" type="number" min="0" max="${media.duration}" step=".1" value="${draft.start}"></div><div class="field"><label for="trim-end">End (seconds)</label><input id="trim-end" type="number" min="0" max="${media.duration}" step=".1" value="${draft.end}"></div></div>`:''}<div class="section-label">YOUR BRAND</div><div class="form-grid"><div class="field"><label for="brand-text">Brand text</label><input id="brand-text" value="${esc(draft.brand)}" maxlength="35" placeholder="Optional brand name"></div><div class="field"><label for="brand-color">Accent colour</label><input type="color" id="brand-color" value="${draft.color||'#d85830'}"></div></div><div class="section-label">CAPTIONS</div><div id="caption-list"></div><button class="button secondary small" data-action="add-caption">${icon('plus')}Add caption</button><p class="help">Enter your own text. Times use seconds from the original video. Automatic transcription is not connected yet.</p><div class="form-actions" style="justify-content:stretch;flex-direction:column">${button(media.kind==='image'?'Export image':'Export video','export','primary','download')}${button('Send for review','request-review','secondary','approve')}</div></aside></div>`;}
let currentSource,currentCanvas,drawFrame,exportController;
async function mountStudio(serial){const media=state.media.find(m=>m.id===routeID());if(!media||media.kind==='audio')return;const url=URL.createObjectURL(media.blob);const source=media.kind==='video'?document.createElement('video'):new Image();source.src=url;if(media.kind==='video'){source.playsInline=true;source.preload='auto';}currentSource=source;currentCanvas=document.querySelector('#preview-canvas');let stopped=false;cleanup=()=>{stopped=true;if(drawFrame)cancelAnimationFrame(drawFrame);source.pause?.();URL.revokeObjectURL(url);currentSource=null;};const draw=()=>{if(stopped||serial!==renderSerial)return;const draft=window.activeDraft;const dims=RATIOS[draft.ratio];if(currentCanvas.width!==dims[0]){[currentCanvas.width,currentCanvas.height]=dims;}else if(currentCanvas.height!==dims[1])currentCanvas.height=dims[1];paint(currentCanvas.getContext('2d'),source,draft,source.currentTime||0);const scrub=document.querySelector('#scrubber');if(scrub){scrub.value=source.currentTime;document.querySelector('#preview-time').textContent=formatTime(source.currentTime);if(!source.paused&&source.currentTime>=Number(draft.end)){source.pause();document.querySelector('#play-preview').innerHTML=icon('play');}}drawFrame=requestAnimationFrame(draw);};source.addEventListener(media.kind==='video'?'loadeddata':'load',()=>{if(stopped)return;if(media.kind==='video')source.currentTime=Number(window.activeDraft.start);draw();},{once:true});source.addEventListener('error',()=>toast('This browser could not preview this file. Try another format.'),{once:true});document.querySelector('#play-preview')?.addEventListener('click',async()=>{if(source.paused){if(source.currentTime>=Number(window.activeDraft.end))source.currentTime=Number(window.activeDraft.start);try{await source.play();document.querySelector('#play-preview').innerHTML=icon('pause');}catch{toast('Unable to play this video.');}}else{source.pause();document.querySelector('#play-preview').innerHTML=icon('play');}});document.querySelector('#scrubber')?.addEventListener('input',e=>source.currentTime=Number(e.target.value));for(const [id,key] of [['draft-title','title'],['crop-position','position'],['trim-start','start'],['trim-end','end'],['brand-text','brand'],['brand-color','color']]){document.getElementById(id)?.addEventListener('input',e=>{window.activeDraft[key]=['position','start','end'].includes(key)?Number(e.target.value):e.target.value;markUnsaved();});}renderCaptions();}
function markUnsaved(){const el=document.querySelector('#draft-status');if(el)el.textContent='Unsaved changes. Save your draft before leaving.';}
function renderCaptions(){const el=document.querySelector('#caption-list');if(!el)return;el.innerHTML=window.activeDraft.captions.map((c,i)=>`<div class="caption-row"><input aria-label="Caption ${i+1} start in seconds" type="number" min="0" step=".1" value="${c.start}" data-caption="${i}" data-key="start"><input aria-label="Caption ${i+1} end in seconds" type="number" min="0" step=".1" value="${c.end}" data-caption="${i}" data-key="end"><button class="icon-button" data-action="remove-caption" data-index="${i}" aria-label="Remove caption ${i+1}">${icon('close')}</button><textarea aria-label="Caption ${i+1} text" data-caption="${i}" data-key="text" maxlength="240">${esc(c.text)}</textarea></div>`).join('');el.querySelectorAll('[data-caption]').forEach(input=>input.addEventListener('input',e=>{window.activeDraft.captions[Number(e.target.dataset.caption)][e.target.dataset.key]=e.target.dataset.key==='text'?e.target.value:Number(e.target.value);markUnsaved();}));}
function researchPage(){const refs=[...state.references].sort((a,b)=>b.created-a.created),summary=researchSummary(refs);return `${heading('Research','Find a pattern worth testing. Keep the evidence close.',button('Save a reference','add-reference','primary','plus'))}<div class="notice">Research starts with links and public metrics you enter. Automatic competitor tracking is not connected. Comparisons are observations, not proof of what caused a result.</div><div class="stats"><div class="stat"><div><small>Saved references</small><strong>${refs.length}</strong></div>${icon('research')}</div><div class="stat"><div><small>With recorded metrics</small><strong>${summary.measured}</strong></div>${icon('grid')}</div><div class="stat"><div><small>Median engagement*</small><strong>${summary.baseline===null?'—':summary.baseline.toFixed(2)+'%'}</strong></div>${icon('leaf')}</div></div><div class="two-col"><section class="panel"><div class="panel-title"><h2>Your reference shelf</h2><span class="pill">Manually sourced</span></div>${refs.length?refs.map(r=>`<article class="reference"><div class="inline"><span class="pill">${esc(r.platform)}</span><span class="small muted">Observed ${dateLabel(r.created)}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.note||'No observation added yet.')}</p><div class="metric-row"><span>${esc(r.format||'Unspecified format')}</span>${engagement(r)!==null?`<span>${engagement(r).toFixed(2)}% engagement*</span>`:'<span>No complete metrics</span>'}</div><div class="inline"><a class="link-button" href="${esc(safeURL(r.url)||'#')}" target="_blank" rel="noopener noreferrer">View source ${icon('external')}</a><div class="inline"><button class="button secondary small" data-action="create-brief" data-id="${r.id}">Make a brief</button><button class="icon-button" data-action="delete-reference" data-id="${r.id}" aria-label="Delete reference">${icon('trash')}</button></div></div></article>`).join(''):empty('research','Keep your inspiration in reach','Save a competitor post, a useful example or a question your audience is asking.','add-reference','Save your first reference')}</section><aside class="panel"><h2>From evidence to an idea.</h2>${summary.ranked.length?`<div class="insight"><span class="eyebrow">HIGHEST RECORDED RATE</span><h3 style="margin-top:12px">${esc(summary.ranked[0].title)}</h3><p>${engagement(summary.ranked[0]).toFixed(2)}% based on the metrics you entered. Review the source before choosing what to test.</p><button class="link-button" data-action="create-brief" data-id="${summary.ranked[0].id}">Turn this into a brief ${icon('arrow')}</button></div>`:''}<div class="insight"><h3>Compare like with like.</h3><p>Choose similar platforms, audiences and observation periods. A bigger account is not automatically a better reference.</p></div><div class="insight"><h3>Borrow the lesson.</h3><p>Look at the opening, topic, format and clarity. Write an original brief that fits your business and audience.</p></div><div class="insight"><h3>Make it an experiment.</h3><p>Plan a post, then record the result. Research becomes useful when it changes your next decision.</p></div><p class="help">* (Recorded reactions + comments) ÷ followers × 100. These figures are manually entered and do not represent private reach, sales or retention.</p></aside></div>`;}
function calendarPage(){const plans=[...state.plans].sort((a,b)=>new Date(a.date)-new Date(b.date));return `${heading('Calendar','Give your next piece of content a place in the week.',button('Plan a post','add-plan','primary','plus'))}<div class="notice">This is a publication plan, not an automatic publishing queue. Export calendar reminders and publish your prepared files yourself until social connections are available. Times below use ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</div><div class="calendar-items">${plans.length?plans.map(p=>`<article class="plan"><div><div class="calendar-day">${new Date(p.date).getDate()}</div><div class="calendar-month">${new Date(p.date).toLocaleDateString(undefined,{month:'short',year:'numeric'})}</div></div><div><h3>${esc(p.title)}</h3><p>${esc(p.channel)} · ${new Date(p.date).toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})} · ${p.status==='done'?'Marked as published manually':'Publishing reminder'}</p>${p.caption?`<p style="margin-top:8px;white-space:pre-wrap">${esc(p.caption)}</p>`:''}</div><div class="inline"><button class="button secondary small" data-action="calendar-export" data-id="${p.id}" aria-label="Export calendar reminder">${icon('download')}.ics</button><button class="icon-button" data-action="toggle-plan" data-id="${p.id}" aria-label="${p.status==='done'?'Mark as planned':'Mark as published manually'}">${icon(p.status==='done'?'undo':'check')}</button><button class="icon-button" data-action="delete-plan" data-id="${p.id}" aria-label="Delete planned post">${icon('trash')}</button></div></article>`).join(''):empty('calendar','A little planning goes a long way.','Add a post, choose its channel and save a reminder to your own calendar.','add-plan','Plan your first post')}</div>`;}
function channelsPage(){return `${heading('Connections','Every channel has a role. Every connection should be clear.')}<div class="notice">Integration roadmap. These services are not connected in this build. Direct publishing, imports and analytics require official API access and platform approval. Prepared files can be downloaded today.</div><div class="panel" style="margin-bottom:25px"><div class="panel-title"><div><h2>Local files</h2><p class="help" style="margin:7px 0 0">Upload from your device. Export prepared images and video.</p></div><span class="pill green">Available now</span></div><div class="inline">${button('Upload content','upload','secondary','upload')}<a class="link-button" href="#studio">Open studio ${icon('arrow')}</a></div></div><div class="channel-grid">${CHANNELS.map(channel=>`<article class="channel"><div class="channel-top"><div class="channel-logo">${esc(channel==='Google Drive'?'GD':channel==='LinkedIn'?'in':channel==='YouTube'?'YT':channel.slice(0,2))}</div><h3>${channel}</h3></div><span class="pill gray">Not connected</span><p>${['Google Drive','Dropbox'].includes(channel)?'Planned import and backup connection.':['SoundCloud','Libsyn','Captivate.fm'].includes(channel)?'Planned audio publishing connection.':channel==='Amazon'?'Commerce video integration to be assessed.':'Publishing and data access to be assessed separately.'}</p><button class="button secondary small" data-action="channel-info" data-channel="${channel}">View availability</button></article>`).join('')}</div>`;}
function approvalsPage(){const drafts=state.drafts.filter(d=>d.status==='review'||d.status==='approved');return `${heading('Approvals','Pause, review and give your content the go-ahead.')}<div class="notice">Personal review checklist. This build records your own approval decisions; inviting clients and team reviewers requires the shared backend.</div><div class="panel">${drafts.length?drafts.map(d=>`<div class="list-row"><div><h3>${esc(d.title)}</h3><p>${d.ratio} · <span class="pill ${d.status==='approved'?'green':'orange'}">${d.status==='approved'?'Approved locally':'Needs review'}</span></p></div><div class="inline"><a class="button secondary small" href="#studio/${d.mediaId}">Review</a>${d.status==='review'?`<button class="button small" data-action="approve-draft" data-id="${d.id}">${icon('check')}Approve</button>`:''}</div></div>`).join(''):empty('approve','A second look, before it goes out.','Send a saved preparation for review from the studio.','go-studio','Open studio')}</div>`;}
function workflowsPage(){return `${heading('Workflows','Save the preparation settings you use again and again.',button('Create a preset','add-workflow','primary','plus'))}<div class="notice">Preparation presets are available now. Apply one to a file to open a prefilled studio draft. Automatic source-to-destination workflows will follow verified social integrations.</div><div class="panel">${state.workflows.length?state.workflows.map(w=>`<div class="list-row"><div><h3>${esc(w.title)}</h3><p>${w.ratio} · ${esc(w.brand||'No brand text')} · Manual preparation preset</p></div><div class="inline"><button class="button secondary small" data-action="apply-workflow" data-id="${w.id}">Use preset ${icon('arrow')}</button><button class="icon-button" data-action="delete-workflow" data-id="${w.id}" aria-label="Delete preset">${icon('trash')}</button></div></div>`).join(''):empty('workflow','Your way of preparing content.','Save a format and brand once, then reuse them on the next file.','add-workflow','Create your first preset')}</div>`;}
function settingsPage(){const size=state.media.reduce((a,m)=>a+m.size,0);return `${heading('Workspace settings','Make this workspace feel like yours.')}<div class="two-col"><section class="panel"><h2>Your default brand</h2><form id="brand-form"><div class="field"><label for="workspace-name">Workspace and brand name</label><input id="workspace-name" name="name" maxlength="35" required value="${esc(state.settings.name)}"></div><div class="field"><label for="workspace-color">Accent colour for exports</label><input id="workspace-color" name="color" type="color" value="${state.settings.color}"></div><p class="help">These defaults apply to new preparations. Existing drafts keep their own settings.</p><button class="button primary" type="submit">Save brand ${icon('check')}</button></form></section><aside class="panel"><h2>Your data, on this device.</h2><p class="small muted">${state.media.length} files · ${formatBytes(size)} of media</p><p class="help">Files and plans are stored with IndexedDB in this browser. They do not sync across devices. Browser storage can be cleared or evicted, so keep your original files.</p><button class="button secondary" data-action="backup">${icon('download')}Export workspace notes</button><p class="help">JSON export includes drafts, references, plans and presets. It excludes media files. Download originals from the media library before clearing browser data.</p><div class="section-label">ABOUT THIS BUILD</div><p class="help">Drop v0.1 · A product by Corebridge.<br>No paid subscription, account system or social connection is active in this personal preview.</p></aside></div>`;}
async function upload(files){if(uploading)return;uploading=true;const errors=[];try{for(const file of files){const status=document.querySelector('#upload-status');if(status)status.innerHTML=`<div class="upload-progress">Preparing ${esc(file.name)}…</div>`;try{const details=await inspect(file);await db.put('media',{id:uid(),name:file.name,type:file.type,size:file.size,created:Date.now(),blob:file,...details});}catch(e){errors.push(`${file.name}: ${e.message}`);}}await refresh();toast(errors.length?errors.join(' · '):'Your files are saved in this browser.');}finally{uploading=false;}}
function bindDrop(){const zone=document.querySelector('#dropzone');if(zone){zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('drag');});zone.addEventListener('dragleave',()=>zone.classList.remove('drag'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('drag');upload(e.dataTransfer.files);});}}
function addReference(){modal('Save a reference','Keep the source and your own observation together.',`<div class="field"><label for="ref-title">Post or reference title</label><input id="ref-title" name="title" required maxlength="160" placeholder="What caught your attention?"></div><div class="field"><label for="ref-url">Source link</label><input id="ref-url" name="url" type="url" required placeholder="https://…"></div><div class="form-grid"><div class="field"><label for="ref-platform">Platform</label><select id="ref-platform" name="platform">${[...CHANNELS,'Website','Other'].map(c=>`<option>${c}</option>`).join('')}</select></div><div class="field"><label for="ref-format">Content format</label><select id="ref-format" name="format"><option>Short video</option><option>Long video</option><option>Image</option><option>Carousel</option><option>Text</option><option>Audio</option></select></div></div><div class="field"><label for="ref-note">Your observation</label><textarea id="ref-note" name="note" maxlength="2000" placeholder="What is worth learning from? What could you test?"></textarea></div><div class="form-grid"><div class="field"><label for="ref-followers">Followers (optional)</label><input id="ref-followers" name="followers" type="number" min="0" step="1"></div><div class="field"><label for="ref-reactions">Reactions (optional)</label><input id="ref-reactions" name="reactions" type="number" min="0" step="1"></div></div><div class="field"><label for="ref-comments">Comments (optional)</label><input id="ref-comments" name="comments" type="number" min="0" step="1"></div><div class="form-actions"><button class="button primary" type="submit">Save reference</button></div>`,async form=>{const data=validateReference(Object.fromEntries(form));await db.put('references',{...data,id:uid(),created:Date.now()});toast('Reference saved.');});}
function addPlan(reference){const now=new Date(Date.now()+3600000);now.setMinutes(now.getMinutes()-now.getTimezoneOffset());modal(reference?'Turn it into a brief':'Plan a post',reference?'Write your own angle, then choose where it belongs.':'Set a reminder for manual publication. This does not publish to a social account.',`<div class="field"><label for="plan-title">${reference?'Your original post idea':'Post title'}</label><input id="plan-title" name="title" required maxlength="160" value="${esc(reference?'Test: '+reference.title:'')}" placeholder="What are you sharing?"></div><div class="form-grid"><div class="field"><label for="plan-channel">Destination</label><select name="channel" id="plan-channel">${CHANNELS.map(c=>`<option ${reference?.platform===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="field"><label for="plan-date">Date and time</label><input type="datetime-local" id="plan-date" name="date" required value="${now.toISOString().slice(0,16)}"></div></div><div class="field"><label for="plan-caption">${reference?'Brief, opening and call to action':'Post description or notes'}</label><textarea id="plan-caption" name="caption" maxlength="5000" placeholder="Write the opening, key points and next step…">${esc(reference?`Observation to test: ${reference.note||'Add your observation.'}\n\nOur original angle:\n\nOpening:\n\nKey points:\n\nCall to action:\n\nSource: ${reference.url}`:'')}</textarea></div><div class="field"><label for="plan-media">Prepared content (optional)</label><select id="plan-media" name="mediaId"><option value="">Choose later</option>${state.media.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><p class="help">Timezone: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}. Export an .ics reminder from Calendar after saving.</p><div class="form-actions"><button class="button primary" type="submit">Save to calendar</button></div>`,async form=>{const data=Object.fromEntries(form);if(!Number.isFinite(+new Date(data.date)))throw new Error('Choose a valid date and time.');await db.put('plans',{...data,id:uid(),date:new Date(data.date).toISOString(),status:'planned',referenceId:reference?.id||null,created:Date.now()});toast('Added to your publication plan.');});}
function addWorkflow(){modal('Create a preparation preset','Save a format and brand for your next file.',`<div class="field"><label for="wf-title">Preset name</label><input id="wf-title" name="title" maxlength="100" required placeholder="Weekly portrait clips"></div><div class="field"><label for="wf-ratio">Format</label><select id="wf-ratio" name="ratio">${Object.keys(RATIOS).map(r=>`<option>${r}</option>`).join('')}</select></div><div class="field"><label for="wf-brand">Brand text</label><input id="wf-brand" name="brand" maxlength="35" value="${esc(state.settings.name)}"></div><div class="field"><label for="wf-color">Brand colour</label><input id="wf-color" type="color" name="color" value="${state.settings.color}"></div><div class="form-actions"><button class="button primary" type="submit">Save preset</button></div>`,async form=>{await db.put('workflows',{...Object.fromEntries(form),id:uid()});toast('Preset saved.');});}
async function saveDraft(status){const media=state.media.find(m=>m.id===routeID()),draft=window.activeDraft;if(!draft?.title.trim())throw new Error('Give this preparation a name.');if(media.kind==='video'&&!validateTrim(draft.start,draft.end,media.duration))throw new Error('Choose valid start and end times within the video.');for(const c of draft.captions){if(!Number.isFinite(c.start)||!Number.isFinite(c.end)||c.start<0||c.end<=c.start)throw new Error('Each caption needs an end time after its start.');if(media.kind==='video'&&c.end>media.duration+.05)throw new Error('Caption times must fit within the original video.');}const record={...draft,status:status||'draft',updated:Date.now()};await db.put('drafts',record);window.activeDraft=record;const i=state.drafts.findIndex(d=>d.id===record.id);if(i===-1)state.drafts.push(record);else state.drafts[i]=record;document.querySelector('#draft-status').textContent=`Saved ${new Date().toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}${status==='review'?' · Ready for review':''}.`;toast(status==='review'?'Added to your review checklist.':'Draft saved.');}
async function doExport(){if(exporting)return;await saveDraft();exporting=true;currentSource?.pause?.();exportController=new AbortController();const overlay=document.createElement('div');overlay.className='busy-overlay';overlay.innerHTML=`<div class="panel"><span class="eyebrow">MAKING YOUR FILE</span><h2 style="margin-top:16px">A new shape for your content.</h2><p class="help">Keep this tab open. Video exports take about as long as the selected clip.</p><progress max="100" value="0" aria-label="Export progress"></progress><p id="export-label" class="small muted">Preparing…</p><button class="button secondary" id="cancel-export">Cancel export</button></div>`;document.body.append(overlay);overlay.querySelector('#cancel-export').onclick=()=>exportController.abort();try{const media=state.media.find(m=>m.id===routeID());const {blob,extension}=await exportMedia(media,structuredClone(window.activeDraft),p=>{overlay.querySelector('progress').value=p;overlay.querySelector('#export-label').textContent=`${Math.round(p)}% · Preparing your export`;},exportController.signal);download(blob,`${window.activeDraft.title.replace(/[^a-zA-Z0-9 -]/g,'').trim()||'drop-export'}-${window.activeDraft.ratio.replace(':','x')}.${extension}`);toast('Your prepared file is ready to download.');}catch(e){toast(e.name==='AbortError'?'Export cancelled. Your draft is saved.':e.message);}finally{overlay.remove();exporting=false;}}
async function confirmRemove(title,description,fn){modal(title,description,`<div class="form-actions"><button class="button secondary" type="button" data-action="close-dialog">Keep it</button><button class="button danger" type="submit">Delete</button></div>`,fn);}
app.addEventListener('click',async e=>{const t=e.target.closest('[data-action],[data-filter],[data-ratio]');if(!t)return;try{if(t.dataset.filter){filter=t.dataset.filter;await render();return;}if(t.dataset.ratio){window.activeDraft.ratio=t.dataset.ratio;document.querySelectorAll('[data-ratio]').forEach(b=>{b.classList.toggle('active',b===t);b.setAttribute('aria-pressed',String(b===t));});markUnsaved();return;}const action=t.dataset.action,id=t.dataset.id;if(action==='upload')document.querySelector('#upload-input').click();else if(action==='go-media')location.hash='media';else if(action==='go-studio')location.hash='studio';else if(action==='menu')document.querySelector('.sidebar').classList.toggle('open');else if(action==='close-dialog')closeDialog();else if(action==='download-original'){const m=state.media.find(m=>m.id===id);download(m.blob,m.name);}else if(action==='rename'){const m=state.media.find(m=>m.id===id);modal('Rename your file','This changes its label in your workspace.',`<div class="field"><label for="rename">File name</label><input id="rename" name="name" value="${esc(m.name)}" required maxlength="200"></div><div class="form-actions"><button class="button primary" type="submit">Save name</button></div>`,async f=>{await db.put('media',{...m,name:f.get('name').trim()||m.name});});}else if(action==='delete-media')confirmRemove('Delete this file?','Its saved preparations will also be removed. Your original file on your device is unaffected.',async()=>{await db.remove('media',id);for(const d of state.drafts.filter(d=>d.mediaId===id))await db.remove('drafts',d.id);for(const p of state.plans.filter(p=>p.mediaId===id))await db.put('plans',{...p,mediaId:''});});else if(action==='add-reference')addReference();else if(action==='create-brief')addPlan(state.references.find(r=>r.id===id));else if(action==='add-plan')addPlan();else if(action==='delete-reference')confirmRemove('Delete this reference?','Its source link and recorded metrics will be removed from your shelf.',()=>db.remove('references',id));else if(action==='delete-plan')confirmRemove('Remove this planned post?','This removes the plan in Drop. Any reminder already exported to your calendar must be removed there separately.',()=>db.remove('plans',id));else if(action==='toggle-plan'){const p=state.plans.find(p=>p.id===id);await db.put('plans',{...p,status:p.status==='done'?'planned':'done'});await refresh();toast('Publication checklist updated. No social post was sent.');}else if(action==='calendar-export'){const p=state.plans.find(p=>p.id===id);download(new Blob([icsEvent(p)],{type:'text/calendar'}),'drop-publication-reminder.ics');}else if(action==='channel-info'){modal(t.dataset.channel,'Connection availability',`<div class="notice">Not connected. This channel is on the roadmap. Official API access, permitted formats, publishing permissions and analytics access will be verified separately.</div><p class="help">Today you can prepare a file in Studio, download it, and publish through the platform itself.</p><div class="form-actions"><button class="button primary" type="submit">Understood</button></div>`,async()=>{});}else if(action==='add-caption'){window.activeDraft.captions.push({start:Number(window.activeDraft.start)||0,end:Number(window.activeDraft.end)||10,text:''});renderCaptions();markUnsaved();}else if(action==='remove-caption'){window.activeDraft.captions.splice(Number(t.dataset.index),1);renderCaptions();markUnsaved();}else if(action==='save-draft')await saveDraft();else if(action==='request-review')await saveDraft('review');else if(action==='approve-draft'){const d=state.drafts.find(d=>d.id===id);await db.put('drafts',{...d,status:'approved',updated:Date.now()});await refresh();toast('Marked approved in your personal workspace.');}else if(action==='export')await doExport();else if(action==='backup'){download(new Blob([JSON.stringify(await db.snapshot(),null,2)],{type:'application/json'}),'drop-workspace-notes.json');}else if(action==='add-workflow')addWorkflow();else if(action==='delete-workflow')confirmRemove('Delete this preset?','Existing preparations will keep their saved settings.',()=>db.remove('workflows',id));else if(action==='apply-workflow'){const w=state.workflows.find(w=>w.id===id);const media=state.media.filter(m=>m.kind!=='audio');if(!media.length){toast('Upload an image or video first.');return;}modal('Use this preset','Choose a file. This will replace its existing preparation settings.',`<div class="field"><label for="preset-file">File</label><select id="preset-file" name="mediaId">${media.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div><div class="form-actions"><button class="button primary" type="submit">Open in studio</button></div>`,async f=>{const m=state.media.find(m=>m.id===f.get('mediaId'));const old=state.drafts.find(d=>d.mediaId===m.id);await db.put('drafts',{id:old?.id||uid(),mediaId:m.id,title:m.name,ratio:w.ratio,brand:w.brand,color:w.color,start:0,end:Math.min(m.duration||10,60),position:.5,captions:[],status:'draft',updated:Date.now()});location.hash=`studio/${m.id}`;});}}catch(error){toast(error.message);}});
dialog.addEventListener('click',e=>{if(e.target.closest('[data-action="close-dialog"]'))closeDialog();});
app.addEventListener('input',e=>{if(e.target.id==='media-search'){const pos=e.target.selectionStart;search=e.target.value;render().then(()=>{const input=document.querySelector('#media-search');input.focus();input.setSelectionRange(pos,pos);});}});
app.addEventListener('submit',async e=>{if(e.target.id!=='brand-form')return;e.preventDefault();try{const form=new FormData(e.target);await db.put('settings',{id:'brand',name:String(form.get('name')).trim()||'My workspace',color:form.get('color')});await refresh();toast('Default brand saved.');}catch(error){toast(error.message);}});
window.addEventListener('hashchange',()=>{if(exporting){exportController?.abort();}render().catch(error=>toast(error.message));});
window.addEventListener('beforeunload',e=>{if(exporting){e.preventDefault();e.returnValue='';}});
(async()=>{try{await db.openDB();await refresh();navigator.storage?.persist?.().catch(()=>{});}catch(error){app.innerHTML=`<div class="error-page"><h1>Your workspace needs browser storage.</h1><p>Allow site storage or open Drop in a normal browser window.</p><p>${esc(error.message)}</p></div>`;}})();
